from lib import *
S = SS('g19')
def tail(lines, sub):
    i = [k for k, l in enumerate(lines) if sub in l][0]
    return lines[i:]
steps = [
    step("for v := range Count(3) 把循环体当作 func(v int) bool 传给迭代器:循环体打印 v = 0、1、2,迭代器最后打印“退出”。break 与 continue:continue 对应循环体返回 true,break 让 yield 返回 false,迭代器打印 yield(3) 返回了 false 并执行 defer;return 写在循环体里(find(5, 2)):yield(2) 返回 false,迭代器退出后外层函数返回 20 true;defer 写在循环体里:要等到外层函数返回才执行,顺序是后进先出(先 v = 1 再 v = 0),而迭代器的“退出”早在循环结束时就已经打印。", t=tl(S(1)), done=lidx(S(1), '循环体 v = 0', '手写等价形式'), mark=lidx(S(1), 'yield(3) 返回了 false', 'yield(2) 返回了 false', '20 true', '[defer] 来自循环体 v = 1', '[defer] 来自循环体 v = 0'), kv=KV([['continue', '循环体返回 true'], ['break', 'yield 返回 false,迭代器执行清理'], ['循环体里 return', 'yield(2) 返回 false;外层函数返回 20 true'], ['循环体里 defer', '外层函数返回时才执行,后进先出']], ['循环体里 defer'])),
    step("循环体里取调用栈(runtime.Callers):main.main-range3 ← main.Count.func1 ← main.main ← runtime.main ← runtime.goexit——循环体是一个叫 main.main-range3 的函数,被迭代器 main.Count.func1 调用,迭代器又被 main.main 调用。", t=tl(S(2)), done=lidx(S(2), 'main.main-range3'), kv=KV([['栈顶', 'main.main-range3(循环体)'], ['再往下', 'main.Count.func1(迭代器)'], ['再往下', 'main.main(包含 for range 的函数)']], ['栈顶'])),
    step("不守规矩的迭代器会被运行时抓住:循环 break 之后迭代器还继续 yield:panic runtime error: range function continued iteration after function for loop body returned false;循环结束后迭代器保存的 yield 又被调用:panic runtime error: range function continued iteration after whole loop exit。", t=tl(S(3)), mark=lidx(S(3), 'break 之后', '循环结束后保存的 yield'), kv=KV([['break 之后继续 yield', 'panic:continued iteration after function for loop body returned false'], ['循环结束后再调用 yield', 'panic:continued iteration after whole loop exit']], ['break 之后继续 yield'])),
    step("标准库的迭代器:slices.Sorted(slices.Values(xs)) = [a b c];slices.Sorted(maps.Keys(m)) = [x y];slices.Collect(strings.SplitSeq(\"a,b,c\", \",\")) = [\"a\" \"b\" \"c\"];strings.Lines 逐行得到 one、two、three;slices.All 得到 (0, \"p\")、(1, \"q\")。", t=tl(S(4)), done=lidx(S(4), 'slices.Sorted', 'SplitSeq', 'strings.Lines', 'slices.All'), kv=KV([['slices.Values / slices.All', '值 / (下标, 值)'], ['maps.Keys', '键的迭代器'], ['strings.SplitSeq / strings.Lines', '不先分配切片的分割与逐行'], ['slices.Sorted / slices.Collect', '把迭代器收集成切片']], ['strings.SplitSeq / strings.Lines'])),
    step("编译器的处理:-m 输出里出现 main-range1、main-range2、main-range3、find-range1 等“-range”后缀的函数(can inline main-range1 等),符号表里有 main.main-range1/2/3、main.find-range1、main.main.func1-range1.deferwrap1——循环体被编译成独立的函数,循环体里的 defer 被包成 deferwrap。", t=tl(S(5)), done=lidx(S(5), 'main-range1', 'main-range2', 'main-range3', 'find-range1'), mark=lidx(S(5), 'deferwrap1'), kv=KV([['循环体', '被编译成 main.main-range1、-range2、-range3 等函数'], ['find 里的循环体', 'find-range1'], ['循环体里的 defer', '被包成 …-range1.deferwrap1']], ['循环体'])),
    step("性能(1000 个 int 求和,7 轮取中位数):for range 切片 302.04 ns/op;迭代器放在 //go:noinline 函数里:自写 Values 2033.25 ns/op、slices.Values 2014.60 ns/op;回调函数 1923.16 ns/op;迭代器与循环体都不加 //go:noinline:304.06 ns/op。分配:SumSeq(Values(xs)) 3 次,SumInl 与 SumSlice 都是 0 次。迭代器没有被内联时每个元素一次间接调用(约 2 ns/个),被内联之后与切片循环一样。", t=tl(S(6)), done=lidx(S(6), 'for range 切片', '不加 //go:noinline'), mark=lidx(S(6), '自写迭代器', 'slices.Values', '回调函数', 'AllocsPerRun'), b=bars([['for range 切片', 302.04, '302'], ['迭代器内联后', 304.06, '304'], ['回调函数', 1923.16, '1923'], ['slices.Values(不内联)', 2014.60, '2015'], ['自写 Values(不内联)', 2033.25, '2033']], 2033.25, done=[0, 1], mark=[2, 3, 4]), kv=KV([['for range 切片', '302.04 ns/op'], ['迭代器未内联', '约 2030 ns/op(约 2 ns / 元素)'], ['迭代器与循环体都内联', '304.06 ns/op,0 次分配'], ['回调函数', '1923.16 ns/op']], ['迭代器未内联'])),
]
A = mkartg('g19', 19, 'Go,迭代器,range over func,iter,编译器,真实验证,动画演示',
    '在 Go 1.27.1 里验证 range-over-func:循环体被编译成 main.main-range1 这样的独立函数并传给迭代器,break 让 yield 返回 false、return 与 defer 的语义、循环体里的调用栈、迭代器违规时运行时会 panic;标准库的 slices、maps、strings 迭代器;迭代器未内联时对 1000 个 int 求和约 2030 ns,比切片循环(302 ns)慢约 6.7 倍,内联后与切片循环一样(304 ns)。',
    'range-over-func 让 for range 可以直接遍历一个函数。它不是魔法:循环体被编译成一个回调,break、return 等被改写成状态变量。这篇用真实输出验证每种控制流的语义,看调用栈与符号,看违规时的 panic,最后量出它的成本。',
    [('main-range3', '循环体被编译成的函数名:调用栈里 main.main-range3 ← main.Count.func1 ← main.main'), ('6.7 倍', '迭代器没有被内联时,对 1000 个 int 求和比切片循环慢(2033 ns vs 302 ns)'), ('304 ns', '迭代器与循环体都能内联时,与切片循环一样快(0 次分配)')],
    [('控制流怎么映射', '<p>循环体就是传给迭代器的 <code>yield</code> 函数:<code>continue</code> 是返回 <code>true</code>,<code>break</code> 是返回 <code>false</code>(迭代器应当随即清理并返回),<code>return</code> 与外层 <code>defer</code> 由编译器用状态变量保证它们属于外层函数——实验里 <code>return</code> 之后迭代器先退出、外层函数再返回,循环体里的 <code>defer</code> 一直等到外层函数结束。</p>'),
     ('调用栈', '<p>在循环体里取调用栈能直接看到这个实现:<code>main.main-range3</code> 是循环体,它的调用者是迭代器 <code>main.Count.func1</code>。panic 或调试时看到 <code>-rangeN</code> 就知道是循环体。</p>'),
     ('违规的迭代器', '<p>迭代器必须在 <code>yield</code> 返回 <code>false</code> 之后马上返回,也不能在循环结束后再调用 <code>yield</code>。运行时会检查这两种情况并 panic,消息里直接写明原因。这类检查保证了 <code>break</code> 等控制流的改写不会被迭代器破坏。</p>'),
     ('标准库', '<p><code>slices</code>、<code>maps</code> 里有成对的迭代器与收集函数(<code>Values</code>、<code>All</code>、<code>Keys</code>、<code>Collect</code>、<code>Sorted</code>),<code>strings</code> 里有 <code>SplitSeq</code>、<code>Lines</code> 等不先分配切片的版本。上面用真实输出演示了它们。</p>'),
     ('编译结果', '<p>-m 与符号表里能看到 <code>-range1</code>、<code>-range2</code> 这类函数,循环体里的 <code>defer</code> 被包装成 <code>deferwrap</code>。这些都是实测输出;编译器重写控制流的具体算法(状态变量的布局等)我没有去读源码。</p>'),
     ('成本', '<p>没有内联时每个元素是一次间接函数调用,约 2 ns,所以求和比切片循环慢约 6.7 倍(回调函数写法也一样);迭代器和循环体都能内联时,编译器把它还原成普通循环,耗时与切片相同、0 次分配。因此“range-over-func 一定慢”或“零成本”都不准确,要看是否内联。注意 //go:noinline 是为了对照而加的,正常代码里小的迭代器通常可以内联。</p>')],
    steps,
    [ENV_G + '。循环体的调用栈来自 runtime.Callers;-m 与符号表来自 go build -gcflags=-m 和 go tool nm;基准测试 7 轮取中位数,迭代器所在函数 //go:noinline(另有一个不加 noinline 的对照)',
     '没有验证:迭代器里 panic 的传播路径与 recover 的位置(见 Pull 一篇)、编译器改写 range-over-func 的具体算法、goto 与标签跳出循环体的各种情形、amd64 上的耗时、迭代器链(多层 Filter/Map)的开销'],
    'range-over-func 迭代器')
